import{c as e,Q as t,j as s,m as o}from"./chunks/framework.DVSyX6JR.js";const u=JSON.parse('{"title":"Atlas telemetry","description":"","frontmatter":{},"headers":[],"relativePath":"docs/atlas.md","filePath":"docs/atlas.md"}'),n={name:"docs/atlas.md"};function d(r,a,l,i,c,p){return t(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="atlas-telemetry" tabindex="-1">Atlas telemetry <a class="header-anchor" href="#atlas-telemetry" aria-label="Permalink to &quot;Atlas telemetry&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Atlas is a disabled-by-default telemetry foundation for future topology, map, observer and network-health tools.</p><p>It does not add internet services, does not change routing behavior, and should not be used as a high-rate beacon system. Phase 1 focuses on compact structures and local export of information the firmware already has.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>atlas enable on</span></span>
<span class="line"><span>atlas position on</span></span>
<span class="line"><span>atlas neighbors on</span></span>
<span class="line"><span>atlas pathsample 1</span></span>
<span class="line"><span>atlas export on</span></span>
<span class="line"><span>get atlas.stats</span></span>
<span class="line"><span>observer export json</span></span></code></pre></div><p><code>atlas pathsample</code> accepts <code>on</code>, <code>off</code>, or a percentage from <code>0</code> to <code>10</code>.</p><p><code>observer export json</code> returns an event-style export only when Atlas and Atlas export are both enabled. Otherwise it returns an empty array.</p><h2 id="payload-allocation" tabindex="-1">Payload allocation <a class="header-anchor" href="#payload-allocation" aria-label="Permalink to &quot;Payload allocation&quot;">​</a></h2><p>Atlas uses <code>PAYLOAD_TYPE_ATLAS</code> (<code>0x0C</code>) with these subtypes:</p><table tabindex="0"><thead><tr><th>Subtype</th><th>Name</th><th>Purpose</th></tr></thead><tbody><tr><td><code>0x01</code></td><td>POSITION</td><td>Compact node position.</td></tr><tr><td><code>0x02</code></td><td>NEIGHBORS</td><td>Low-rate neighbor summary.</td></tr><tr><td><code>0x03</code></td><td>PATH_SAMPLE</td><td>Sampled route telemetry.</td></tr><tr><td><code>0x04</code></td><td>DENSE_STATS</td><td>Network-health counters.</td></tr></tbody></table><h2 id="future-integrations" tabindex="-1">Future integrations <a class="header-anchor" href="#future-integrations" aria-label="Permalink to &quot;Future integrations&quot;">​</a></h2><p>Atlas is intended to feed external tooling such as dashboards, MQTT gateways, Home Assistant bridges or map views. The firmware should export clean local data and let a gateway handle heavier jobs like TLS, MQTT discovery, databases and visualization.</p>`,13)])])}const m=e(n,[["render",d]]);export{u as __pageData,m as default};
